export const countryByCode=new Map(countries.map(item=>[item.code,item]));
export const countryCodes=new Set(countries.map(item=>item.code));
export function validateTaxId(countryCode:string,value:string):boolean|null{
 const country=countryByCode.get(countryCode.toUpperCase());if(!country?.taxId)return null;
 try{return new RegExp(country.taxId.pattern,"i").test(value.trim());}catch{return null;}
}
